package com.cob.emr.ddd.domain.medicalnote.model.valueobjects;public enum TimePeriod {    TWO_WEEK("2-week"),    FOUR_WEEK("4-week"),    SIX_WEEK("6-week"),    EIGHT_WEEK("8-week"),    CUSTOM("custom");    private final String value;    TimePeriod(String value) {        this.value = value;    }    public String getValue() {        return value;    }    public static TimePeriod fromString(String value) {        for (TimePeriod period : values()) {            if (period.value.equals(value)) {                return period;            }        }        return CUSTOM;    }}
